sql.where:
clan_id = #{criteria.clanId}

  AND branch_id = #{criteria.branchId}


  AND status = #{criteria.status}


  AND (
    import_type = #{criteria.importType}
    OR import_type = #{criteria.importType} || '_csv'
    OR import_type = #{criteria.importType} || '_xlsx'
  )


  AND (
    file_format = #{criteria.fileFormat}
    OR (
      file_format IS NULL
      AND import_type LIKE '%_' || #{criteria.fileFormat}
    )
  )

